  "wintergreen": {
    "family": {
      "value": "Ericaceae",
      "source": {
        "name": "Wikidata",
        "url": "https://www.wikidata.org/wiki/Q386770",
        "retrieved": "2026-10-29"
      }
    },
    "traditionalNames": {
      "value": [
        "eastern teaberry"
      ],
      "source": {
        "name": "Wikidata",
        "url": "https://www.wikidata.org/wiki/Q386770",
        "retrieved": "2026-10-29"
      }
    },
    "description": {
      "value": "Gaultheria procumbens, also called the eastern teaberry, the checkerberry, the boxberry, or the American wintergreen, is a perennial species of Gaultheria native to northeastern North America from Newfoundland west to southeastern Manitoba, and south to Alabama. It is a member of the Ericaceae (heath family).",
      "source": {
        "name": "Wikipedia",
        "url": "https://en.wikipedia.org/wiki/Gaultheria_procumbens",
        "retrieved": "2026-10-29"
      }
    },
    "distribution": {
      "value": "G. procumbens is a small, low-growing shrub, typically reaching 10–15 cm (4–6 in) tall. The leaves are evergreen, elliptic to ovate, 2–5 cm (3⁄4–2 in) long and 1–2 cm (1⁄2–3⁄4 in) broad, with a distinct oil of wintergreen scent. The flowers are pendulous, with a white, sometimes pink-tinged, bell-shaped corolla with five teeth at the tip 8–10 mm (0.31–0.39 in) long, and above it a white calyx. They are borne in leaf axils, usually one to three per stem. The anthers are forked somewhat like a snake's tongue, with two awns at the tip. The fruit is red and 6–9 mm (0.24–0.35 in) across.",
      "source": {
        "name": "Wikipedia",
        "url": "https://en.wikipedia.org/wiki/Gaultheria_procumbens",
        "retrieved": "2026-10-29"
      }
    }
  },
  "st-johns-wort": {
    "family": {
      "value": "Hypericaceae",
      "source": {
        "name": "Wikidata",
        "url": "https://www.wikidata.org/wiki/Q158289",
        "retrieved": "2026-10-29"
      }
    },
    "traditionalNames": {
      "value": [
        "Common St. John's wort",
        "perforate St. Johns-wort"
      ],
      "source": {
        "name": "Wikidata",
        "url": "https://www.wikidata.org/wiki/Q158289",
        "retrieved": "2026-10-29"
      }
    },
    "description": {
      "value": "Hypericum perforatum is an herbaceous perennial plant with hairless (glabrous) stems and leaves. The root of each plant is slender and woody with many small, fibrous small side roots and also extensive, creeping rhizomes. The central root grows to a depth of 0.6–1.5 metres (2 ft 0 in – 4 ft 11 in) into the soil depending on conditions. The crown of the root is woody. Its stems are erect and branched in the upper section, and usually range from 0.3 metres to 1 metre in height.",
      "source": {
        "name": "Wikipedia",
        "url": "https://en.wikipedia.org/wiki/Hypericum_perforatum",
        "retrieved": "2026-10-29"
      }
    },
    "distribution": {
      "value": "Hypericum perforatum is thought to be native to every nation in Europe, and is only absent from the far north such as north European Russia and Svalbard. It grows in parts of North Africa and is native to Morocco, Algeria, Tunisia, and Sudan. In the Arabian Peninsula it only grows in parts of Saudi Arabia. It is present and native to all of the Western Asia phytogeographic region from the Aegean Islands and Turkey to Israel and Palestine in the west to Afghanistan in the east, only being absent from the Sinai Peninsula.",
      "source": {
        "name": "Wikipedia",
        "url": "https://en.wikipedia.org/wiki/Hypericum_perforatum",
        "retrieved": "2026-10-29"
      }
    },
    "constituents": {
      "value": "The most common active chemicals in Hypericum perforatum are hypericin and pseudohypericin (naphthodianthrones), and hyperforin (a phloroglucinol derivative). The species contains a host of essential oils, the bulk of which are sesquiterpenes. In the wild, the concentrations of any active chemicals can vary widely among individual plants and populations. Notes:",
      "source": {
        "name": "Wikipedia",
        "url": "https://en.wikipedia.org/wiki/Hypericum_perforatum",
        "retrieved": "2026-10-29"
      }
    }
  },
