  "partridgeberry": {
    "family": {
      "value": "Rubiaceae",
      "source": {
        "name": "Wikidata",
        "url": "https://www.wikidata.org/wiki/Q1401376",
        "retrieved": "2026-10-29"
      }
    },
    "description": {
      "value": "The partridge berry is an evergreen plant growing as a non-climbing vine, no taller than 6 cm tall with creeping stems 15 to 30 cm long. The evergreen, dark green, shiny leaves are ovate to cordate in shape. The leaves have a pale yellow midrib. The petioles are short, and the leaves are paired oppositely on the stems. Adventitious roots may grow at the nodes; and rooting stems may branch and root repeatedly, producing loose spreading mats. The small, trumpet-shaped, axillary flowers are produced in pairs, and each flower pair arises from one common calyx which is covered with fine hairs.",
      "source": {
        "name": "Wikipedia",
        "url": "https://en.wikipedia.org/wiki/Mitchella_repens",
        "retrieved": "2026-10-29"
      }
    },
    "distribution": {
      "value": "The species is distributed throughout eastern North America, from south Eastern Canada south to Florida and Texas, and to Guatemala. It is found growing in dry or moist woods, along stream banks and on sandy slopes.",
      "source": {
        "name": "Wikipedia",
        "url": "https://en.wikipedia.org/wiki/Mitchella_repens",
        "retrieved": "2026-10-29"
      }
    },
    "cultivation": {
      "value": "Mitchella repens is cultivated for its ornamental red berries and shiny, bright green foliage. It is grown as a creeping ground cover in shady locations. It is rarely propagated for garden use by way of seeds but cuttings are easy. The plants have been widely collected for Christmas decorations, and over collecting has affected some local populations negatively. The plants are sometimes grown in terrariums. The scarlet berries are edible but rather tasteless, with a faint flavour of wintergreen, resembling cranberries (to which they are not closely related).",
      "source": {
        "name": "Wikipedia",
        "url": "https://en.wikipedia.org/wiki/Mitchella_repens",
        "retrieved": "2026-10-29"
      }
    }
  },
