  "licorice-root-2": {
    "family": {
      "value": "Fabaceae",
      "source": {
        "name": "Wikidata",
        "url": "https://www.wikidata.org/wiki/Q257106",
        "retrieved": "2026-10-29"
      }
    },
    "description": {
      "value": "Liquorice is a herbaceous perennial, growing to 1 metre (40 in) in height, with pinnate leaves about 7–15 cm (3–6 in) long, with 9–17 leaflets. The flowers are 8–12 mm (5⁄16–1⁄2 in) long, purple to pale whitish blue, produced in a loose inflorescence. The fruit is an oblong pod, 20–30 mm (3⁄4–1+1⁄8 in) long, containing several seeds. The roots are stoloniferous.",
      "source": {
        "name": "Wikipedia",
        "url": "https://en.wikipedia.org/wiki/Liquorice",
        "retrieved": "2026-10-29"
      }
    },
    "cultivation": {
      "value": "Liquorice grows best in well-drained soils in deep valleys with full sun. It is harvested in the autumn two to three years after planting. Countries producing liquorice include Turkey, Greece, Iran, and Iraq.",
      "source": {
        "name": "Wikipedia",
        "url": "https://en.wikipedia.org/wiki/Liquorice",
        "retrieved": "2026-10-29"
      }
    },
    "constituents": {
      "value": "Liquorice root contains triterpenoids, polyphenols, and polysaccharides. Flavonoids account for the yellow root colour. The principal glycoside, glycyrrhizin, exists in content of 7% to 10%, depending on cultivation practices. The isoflavene glabrene and the isoflavane glabridin, found in the roots of liquorice, are phytoestrogens. The scent of liquorice root comes from a complex and variable combination of compounds, of which anethole is some 3% of total volatiles. Much of the sweetness in liquorice comes from glycyrrhizin, which has 30–50 times the sweetness of sugar.",
      "source": {
        "name": "Wikipedia",
        "url": "https://en.wikipedia.org/wiki/Liquorice",
        "retrieved": "2026-10-29"
      }
    }
  },
