  "horse-chestnut": {
    "family": {
      "value": "Sapindaceae",
      "source": {
        "name": "Wikidata",
        "url": "https://www.wikidata.org/wiki/Q26899",
        "retrieved": "2026-10-29"
      }
    },
    "traditionalNames": {
      "value": [
        "conker tree",
        "horse chestnut tree",
        "horse-chestnut",
        "white horse chestnut",
        "common horse chestnut",
        "European horse chestnut",
        "European horsechestnut",
        "buckeye"
      ],
      "source": {
        "name": "Wikidata",
        "url": "https://www.wikidata.org/wiki/Q26899",
        "retrieved": "2026-10-29"
      }
    },
    "description": {
      "value": "Aesculus hippocastanum is a large tree, growing to about 39 m (128 ft) tall with a domed crown of stout branches. On old trees, the outer branches are often pendulous with curled-up tips. The leaves are opposite and palmately compound, with 5–7 leaflets 13–30 cm (5–12 in) long, making the whole leaf up to 60 cm (24 in) across, with a 7–20 cm (3–8 in) petiole. The leaf scars, left on twigs after leaves fall, have a distinctive horseshoe shape, complete with seven \"nails\". In late spring, polygamomonoecious erect panicles of about 4–5 flowers bloom from jointed pedicels.",
      "source": {
        "name": "Wikipedia",
        "url": "https://en.wikipedia.org/wiki/Aesculus_hippocastanum",
        "retrieved": "2026-10-29"
      }
    },
    "distribution": {
      "value": "The native distribution of Aesculus hippocastanum given by different sources varies. As of March 2023, Plants of the World Online considered it to be native to the Balkans (Albania, Bulgaria, Greece and former Yugoslavia), but also to Turkey and Turkmenistan. A 2017 assessment for the IUCN Red List restricted the native distribution to the Balkan area: Albania, Bulgaria, mainland Greece and North Macedonia. It has been introduced and planted around the world.",
      "source": {
        "name": "Wikipedia",
        "url": "https://en.wikipedia.org/wiki/Aesculus_hippocastanum",
        "retrieved": "2026-10-29"
      }
    },
    "cultivation": {
      "value": "It is widely cultivated in streets and parks throughout the temperate world, and has been particularly successful in places like Ireland, Great Britain and New Zealand, where it is commonly found in parks, streets and avenues. Cultivation for its spectacular spring flowers is successful in a wide range of temperate climatic conditions provided summers are not too hot, with trees being grown as far north as Edmonton, Alberta, Canada, the Faroe Islands, Reykjavík, Iceland and Harstad, Norway. The horse-chestnut is a favorite subject for bonsai.",
      "source": {
        "name": "Wikipedia",
        "url": "https://en.wikipedia.org/wiki/Aesculus_hippocastanum",
        "retrieved": "2026-10-29"
      }
    }
  },
  "butchers-broom": {
    "family": {
      "value": "Solanaceae",
      "source": {
        "name": "Wikidata",
        "url": "https://www.wikidata.org/wiki/Q161425",
        "retrieved": "2026-10-29"
      }
    },
    "traditionalNames": {
      "value": [
        "kneeholm"
      ],
      "source": {
        "name": "Wikidata",
        "url": "https://www.wikidata.org/wiki/Q161425",
        "retrieved": "2026-10-29"
      }
    },
    "description": {
      "value": "Grows to length of 80 cm (31 in) with stiff branches bearing cladodes (stems modified to look like leaves) up to 4 cm (1.6 in) long, while the true leaves are reduced to scales less than 5 mm. Flowers grow from axils of small bracts on the adaxial (upper) side of cladodes. The 6 tepals are pale green, and the ovary or stamens are violet (dioecious plant). Fruit about 1 cm red, thick and rigid.",
      "source": {
        "name": "Wikipedia",
        "url": "https://en.wikipedia.org/wiki/Ruscus_aculeatus",
        "retrieved": "2026-10-29"
      }
    },
    "distribution": {
      "value": "In Great Britain it has been recorded from southern England to north Wales. In north-eastern Ireland it is extremely rare growing wild but has been recorded in Counties Down and Antrim.",
      "source": {
        "name": "Wikipedia",
        "url": "https://en.wikipedia.org/wiki/Ruscus_aculeatus",
        "retrieved": "2026-10-29"
      }
    },
    "constituents": {
      "value": "The major phytochemicals in butcher's broom are steroidal saponins. Saponins occur naturally in plants as glycosides and have foam forming properties. The specific saponins found in butcher's broom are ruscogenins, ruscogenen and neoruscogenin, named for the genus Ruscus. Ruscogenins function as anti-inflammatory agents and are also believed to cause constriction in veins. Currently the mode of action of ruscogenins is not well understood, but one proposed mechanism suggests that ruscogenins suppresses leukocyte migration through both protein and mRNA regulation.",
      "source": {
        "name": "Wikipedia",
        "url": "https://en.wikipedia.org/wiki/Ruscus_aculeatus",
        "retrieved": "2026-10-29"
      }
    }
  },
  "ginkgo": {
    "family": {
      "value": "Ginkgoaceae",
      "source": {
        "name": "Wikidata",
        "url": "https://www.wikidata.org/wiki/Q43284",
        "retrieved": "2026-10-29"
      }
    },
    "traditionalNames": {
      "value": [
        "maidenhair tree",
        "silver apricot",
        "ginkgo plant",
        "ginkgo tree",
        "ginkgo"
      ],
      "source": {
        "name": "Wikidata",
        "url": "https://www.wikidata.org/wiki/Q43284",
        "retrieved": "2026-10-29"
      }
    },
    "description": {
      "value": "Ginkgos have a conical crown in youth which becomes progressively broader and more irregular with age. They are large trees, normally reaching a height of 20–35 m (66–115 ft), with some specimens in China being over 40 m (130 ft). The tree has an angular crown and long, somewhat erratic branches, and is usually deep-rooted and resistant to wind and snow damage. Young trees are often tall and slender, and sparsely branched; the crown becomes broader as the tree ages.",
      "source": {
        "name": "Wikipedia",
        "url": "https://en.wikipedia.org/wiki/Ginkgo_biloba",
        "retrieved": "2026-10-29"
      }
    },
    "distribution": {
      "value": "Although Ginkgo biloba and other species of the genus were once widespread throughout the world, its habitat had shrunk by two million years ago. For centuries, it was thought to be extinct in the wild, but is now a common tree cultivated throughout eastern China, Korea, and Japan. Many municipalities in China, Korea and Japan use ginkgos as street trees, and ginkgo leaves are the emblem of prominent educational institutions such as the University of Tokyo and Sungkyunkwan University in South Korea.",
      "source": {
        "name": "Wikipedia",
        "url": "https://en.wikipedia.org/wiki/Ginkgo_biloba",
        "retrieved": "2026-10-29"
      }
    },
    "cultivation": {
      "value": "Ginkgo has long been cultivated in China. It is common in the southern third of the country. Some planted trees at temples are believed to be over 1,500 years old. The first record of Europeans encountering it is in 1690 in Japanese temple gardens, where the tree was seen by the German botanist Engelbert Kaempfer. Because of its status in Buddhism and Confucianism, the ginkgo has also been widely planted in Korea and in Japan since the 14th century; in both areas, some naturalization has occurred, with ginkgos seeding into natural forests.",
      "source": {
        "name": "Wikipedia",
        "url": "https://en.wikipedia.org/wiki/Ginkgo_biloba",
        "retrieved": "2026-10-29"
      }
    },
    "constituents": {
      "value": "Extracts of ginkgo leaves contain phenolic acids, proanthocyanidins, flavonoid glycosides, such as myricetin, kaempferol, isorhamnetin, and quercetin, and the terpene trilactones ginkgolides and bilobalides. The leaves also contain unique ginkgo biflavones, alkylphenols, and polyprenols.",
      "source": {
        "name": "Wikipedia",
        "url": "https://en.wikipedia.org/wiki/Ginkgo_biloba",
        "retrieved": "2026-10-29"
      }
    }
  },
